    const view = new DataView(data.buffer);
    const isLE = true;

    // Read ELF header
    const e_type = view.getUint16(16, isLE);        
    const e_machine = view.getUint16(18, isLE);     
    const e_entry = view.getBigUint64(24, isLE);
    const e_phoff = view.getBigUint64(32, isLE);
    const e_shoff = view.getBigUint64(40, isLE);
    const e_phentsize = view.getUint16(54, isLE);
    const e_phnum = view.getUint16(56, isLE);
    const e_shentsize = view.getUint16(58, isLE);
    const e_shnum = view.getUint16(60, isLE);

    const result = {};

    // Parse program headers to find loadable segments
    for (let i = 0; i < e_phnum; i++) {
        const phOffset = Number(e_phoff) + i * e_phentsize;
        const p_type = view.getUint32(phOffset + 0, isLE);
        const p_flags = view.getUint32(phOffset + 4, isLE);
        const p_offset = Number(view.getBigUint64(phOffset + 8, isLE));
        const p_vaddr = Number(view.getBigUint64(phOffset + 16, isLE));
        const p_filesz = Number(view.getBigUint64(phOffset + 32, isLE));
